-- border colors cached by `wallborders` (run on every wallpaper switch via `wp`)
local function readBorderCache()
  local f = io.open(os.getenv("HOME") .. "/.cache/mybar/border.conf", "r")
  if not f then return nil end
  local a, b = f:read("*l"), f:read("*l")
  f:close()
  if a and b and #a > 0 and #b > 0 then return a, b end
end
local borderA, borderB = readBorderCache()


