-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
hl.on("hyprland.start", function()
  -- awww: runtime-switchable wallpaper daemon (remembers last via `awww restore`)
  hl.exec_cmd("awww-daemon")
  hl.exec_cmd("sh -c 'sleep 1; awww restore || awww img ~/WALLPAPERS/04-ambxst-blobs-blue.png'")
  hl.exec_cmd("quickshell -p ~/.config/quickshell/mybar/shell.qml")
  hl.exec_cmd("sh -c 'pgrep -f /.local/bin/lockart >/dev/null || /home/octal/.local/bin/lockart'")
  hl.exec_cmd("sh -c 'pgrep -x hypridle >/dev/null || hypridle'")
end)


