---- HYPRLIQUID GLASS ----
--------------------------------
-- Manual install path (hyprpm build needs `stb` package). Already loaded? `hyprctl plugin list` shows 0.2.0.
-- liquid glass plugin: prefer manual build, fall back to system install paths
for _, p in ipairs({
  os.getenv("HOME") .. "/.local/lib/hyprliquid.so",
  "/usr/lib/hyprliquid.so",
  "/usr/lib/libhyprliquid.so",
}) do
  local f = io.open(p, "r")
  if f then f:close(); hl.plugin.load(p); break end
end

if hl.plugin.hyprliquid then
  -- global glass defaults (tuned live from dashboard: thickness + corner radius)
  hl.config({
    plugin = {
      hyprliquid = {
        corner_radius = 16,
        glass_thickness = 500,
      },
    },
  })

  -- kitty terminal: minimal liquid glass (faint tint, plain edge, no dispersion)
  hl.window_rule({
    name = "kitty-glass",
    match = { class = "kitty" },
    border_size = 0,
    no_blur = true,
    no_shadow = true,
    ["hyprliquid:rounding_lua"] = 18,
    ["hyprliquid:effect"] = "liquid_glass",
    ["hyprliquid:tint_color"] = "rgba(0x11, 0x11, 0x1b, 0.18)",
    ["hyprliquid:highlight_style"] = 1,
    ["hyprliquid:force_full_damage"] = true,
    ["hyprliquid:glass_dispersion"] = false,
  })

  -- mybar quickshell bar: minimal liquid glass pill
  hl.layer_rule({
    name = "mybar-glass",
    match = { namespace = "mybar" },
    ["hyprliquid:effect"] = "liquid_glass",
    ["hyprliquid:highlight_style"] = 1,
    ["hyprliquid:force_full_damage"] = true,
    ["hyprliquid:vdf_map_mode"] = 1,
    ["hyprliquid:vdf_map_update_policy"] = "always",
